import { HttpErrorResponse, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { StepUpService } from './step-up.service';
import { Injectable } from '@angular/core';
import { catchError, EMPTY, throwError } from 'rxjs';

/* @autogenerated */
@Injectable()
export class StepUpInterceptor implements HttpInterceptor {
  constructor(private stepUp: StepUpService) {}

  intercept(req: HttpRequest<any>, next: HttpHandler) {
    return next.handle(req).pipe(
      catchError((err: HttpErrorResponse) => {
        const h = err.headers?.get('WWW-Authenticate') ?? '';
        if (err.status === 401 && h.includes('insufficient_user_authentication')) {
          const acr = /acr_values="([^"]+)"/.exec(h)?.[1];
          const maxAge = /max_age=(\d+)/.exec(h)?.[1];
          this.stepUp.start(req, acr, maxAge); // redirige; no vuelve
          return EMPTY;
        }
        return throwError(() => err);
      }),
    );
  }
}
